// new Cookie(name, value)   - tworzy ciasteczko
// cookie.setMaxAge(sekundy) - czas zycia (bez tego -> cookie
//                             sesyjne, znika po zamknieciu przegladarki)
// cookie.setPath("/")       - dla jakich sciezek przegladarka
//                             ma je odsylac
// response.addCookie(cookie) - dopisuje naglowek Set-Cookie

Cookie cookie = new Cookie("odwiedziny", "tak");
cookie.setMaxAge(3600); // 1 godzina
cookie.setPath("/");
resp.addCookie(cookie);

HttpClient client = HttpClient.newBuilder()
        .cookieHandler(new CookieManager())
        .build();

// Zadanie 1: serwer ustawia cookie
HttpResponse<String> response1 = client.send(request1, HttpResponse.BodyHandlers.ofString());

// Zadanie 2: TEN SAM klient, cookie odeslane automatycznie
HttpResponse<String> response2 = client.send(request2, HttpResponse.BodyHandlers.ofString());
// serwer w Body drugiej odpowiedzi POWINIEN pokazac, ze
// ODCZYTAL cookie ustawione w zadaniu 1 (req.getCookies())

Cookie[] cookies = req.getCookies();
// UWAGA: MOZE BYC null, gdy klient nie przyslal ZADNYCH cookies!
String odczytanaWartosc = null;
if (cookies != null) {
    for (Cookie c : cookies) {
        if ("odwiedziny".equals(c.getName())) {
            odczytanaWartosc = c.getValue();
        }
    }
}

if (odczytanaWartosc != null) {
    sb.append("Witaj ponownie! Odczytano cookie = ").append(odczytanaWartosc);
} else {
    sb.append("Brak cookie w zadaniu.");
